begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('customers','customer_addresses','stock_reservations','checkout_operations','storefront_checkout_settings') and c.relrowsecurity),5::bigint,'all online tables enable RLS');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.oid=c.relowner where n.nspname='public' and c.relname in ('customers','customer_addresses','stock_reservations','checkout_operations','storefront_checkout_settings') and r.rolname='online_writer'),5::bigint,'non-login writer owns online tables');
select ok((select not rolcanlogin and not rolbypassrls from pg_roles where rolname='online_writer'),'writer cannot log in or bypass other RLS');
select ok(not pg_has_role('service_role','online_writer','MEMBER'),'service cannot become writer');
select ok(not has_schema_privilege('anon','online_private','USAGE'),'anon has no online RPC schema access');
select ok(not has_schema_privilege('authenticated','online_private','USAGE'),'authenticated has no online RPC schema access');
select ok(not has_table_privilege('anon','public.customers','SELECT'),'anon cannot inspect customer lookup fields');
select ok(not has_table_privilege('authenticated','public.customers','SELECT'),'workforce JWT alone cannot inspect customers');
select ok(not has_table_privilege('authenticated','public.customer_addresses','SELECT'),'saved addresses require server authorization');
select ok(not has_table_privilege('anon','public.stock_reservations','SELECT'),'stock commitments are private');
select ok(not has_table_privilege('authenticated','public.checkout_operations','SELECT'),'retry intents and customer PII are private');
select ok(not has_table_privilege('anon','public.storefront_checkout_settings','SELECT'),'routing is private');
select ok(not has_table_privilege('service_role','public.customers','INSERT'),'service cannot directly create customer artifacts');
select ok(not has_table_privilege('service_role','public.stock_reservations','UPDATE'),'service cannot bypass reservation transitions');
select ok(not has_table_privilege('service_role','public.checkout_operations','DELETE'),'service cannot erase idempotency history');
select ok(has_function_privilege('service_role','online_private.place_checkout(text,jsonb)','EXECUTE'),'service can invoke atomic placement');
select ok(not has_function_privilege('service_role','online_private.consume_reservations(uuid,uuid,uuid,jsonb)','EXECUTE'),'service cannot consume without canonical fulfillment');
select ok(not has_function_privilege('service_role','payments_private.transition_payment(uuid,uuid,text)','EXECUTE'),'service cannot claim payment success directly');
select ok(not has_function_privilege('service_role','orders_private.attach_checkout_customer(uuid,uuid,uuid,jsonb,jsonb)','EXECUTE'),'service cannot rewrite order snapshots');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='online_private' and (not p.prosecdef or not p.proconfig @> array['search_path=""'])),0::bigint,'all online entrypoints are hardened definers');
select * from finish();
rollback;
